#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic() {
        let m = word_count("the cat sat the cat");
        assert_eq!(m["the"], 2);
        assert_eq!(m["cat"], 2);
        assert_eq!(m["sat"], 1);
    }

    #[test]
    fn test_case_insensitive() {
        let m = word_count("Hello hello HELLO");
        assert_eq!(m["hello"], 3);
    }

    #[test]
    fn test_empty() {
        let m = word_count("");
        assert!(m.is_empty());
    }
}

